SELECT

FROM PERF_KPI_SCHEME


        AND cycle_type = #{cycleType}


        AND status = #{status}


        AND (
            scheme_code LIKE CONCAT('%', #{keyword}, '%')
            OR scheme_name LIKE CONCAT('%', #{keyword}, '%')
        )


        AND open_detail = #{openDetail}


ORDER BY created_time DESC, scheme_name ASC
LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*)
FROM PERF_KPI_SCHEME


        AND cycle_type = #{cycleType}


        AND status = #{status}


        AND (
            scheme_code LIKE CONCAT('%', #{keyword}, '%')
            OR scheme_name LIKE CONCAT('%', #{keyword}, '%')
        )


        AND open_detail = #{openDetail}
